<div ng-app="sitaraAdmin" ng-controller="letterNumberFormatController" ng-cloak>
  <div class="alert alert-danger" ng-if="errorMessage" ng-bind="errorMessage"></div><div class="alert alert-success" ng-if="successMessage" ng-bind="successMessage"></div>
  <article class="card sitara-card mb-4"><div class="card-header"><h2 class="sitara-card-title">Format nomor surat per jenis kegiatan</h2><p class="sitara-card-subtitle mb-0">Placeholder: {nomor}, {kode_surat}, {kode_prodi}, {bulan_romawi}, {tahun}, {kode_kegiatan}</p></div><div class="card-body"><form ng-submit="save()" class="row g-3 align-items-end"><div class="col-md-3"><label class="form-label">Jenis kegiatan <span class="required-mark">*</span></label><select class="form-select" ng-model="model.activity_type_id" ng-options="x.id as (x.code+' — '+x.name) for x in activityTypes" required><option value="">Pilih kegiatan</option></select></div><div class="col-md-4"><label class="form-label">Format <span class="required-mark">*</span></label><input class="form-control" ng-model="model.format_template" required></div><div class="col-md-2"><label class="form-label">Kode surat</label><input class="form-control" ng-model="model.letter_code"></div><div class="col-md-1"><label class="form-label">Digit</label><input type="number" min="1" max="6" class="form-control" ng-model="model.padding"></div><div class="col-md-2"><label class="form-label">Reset</label><select class="form-select" ng-model="model.reset_scope"><option value="TAHUN">Tiap tahun</option><option value="PERIODE">Tiap periode</option></select></div><div class="col-12 text-end"><button class="btn btn-primary" type="submit" ng-disabled="saving" ng-bind="saving?'Menyimpan...':'Simpan format'"></button></div></form></div></article>
  <article class="card sitara-card"><div class="card-header"><h2 class="sitara-card-title">Format tersimpan</h2></div><div class="table-responsive"><table class="table sitara-table mb-0"><thead><tr><th>Jenis kegiatan</th><th>Format</th><th>Kode</th><th>Nomor berikutnya</th><th>Reset</th><th>Aksi</th></tr></thead><tbody><tr ng-repeat="x in formats track by x.id"><td ng-bind="x.activity_code+' — '+x.activity_name"></td><td><code ng-bind="x.format_template"></code></td><td ng-bind="x.letter_code"></td><td ng-bind="x.next_number"></td><td ng-bind="x.reset_scope"></td><td><button class="btn btn-sm btn-outline-primary" ng-click="edit(x)">Ubah</button></td></tr><tr ng-if="!formats.length"><td colspan="6" class="sitara-empty">Belum ada format.</td></tr></tbody></table></div></article>
